<script setup lang="ts">
import{onMounted,ref}from 'vue';import{useRoute}from 'vue-router';import{seriesStore,loadSeries,loadObservations}from '../stores/series';import{createSeries,addObservation}from '../api/series';import{canEdit}from '../stores/auth';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import SeriesTable from '../components/SeriesTable.vue';import ForecastChart from '../components/ForecastChart.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';
const{error,busy,execute}=useTask();const selected=ref(1),showCreate=ref(false);const form=ref({code:'',name:'',city:'',product:''});const point=ref({day:'2026-11-12',value:150});const route=useRoute();
const choose=(id:number)=>execute(async()=>{selected.value=id;await loadObservations(id)});const refresh=()=>execute(async()=>{await loadSeries();if(seriesStore.items.length)await choose(Number(route.query.selected)||seriesStore.items[0].id)});
const save=()=>execute(async()=>{await createSeries(form.value);showCreate.value=false;await loadSeries()});const add=()=>execute(async()=>{await addObservation(selected.value,point.value);await loadObservations(selected.value);await loadSeries()});onMounted(refresh);
</script><template><PageHeading index="02 / OBSERVATIONS" title="序列台账" subtitle="按城市与花材检查每日需求，日期连续的序列才能进入回测。"/><ErrorNotice :message="error" @retry="refresh"/><div class="section-heading"><h2>上游观测目录</h2><button v-if="canEdit" @click="showCreate=!showCreate">{{showCreate?'收起':'＋ 新建序列'}}</button></div><form v-if="showCreate" class="form-grid" @submit.prevent="save"><label v-for="(_,key) in form" :key="key">{{{code:'唯一编码（小写英文）',name:'序列名称',city:'城市',product:'花材'}[key]}}<input v-model="form[key]" required/></label><button class="primary" :disabled="busy">保存序列</button></form><SeriesTable :items="seriesStore.items" @select="choose"/><div class="section-heading"><h2>最近 42 天 · {{seriesStore.items.find(s=>s.id===selected)?.name}}</h2><span>每日实测 / 单位：束</span></div><ForecastChart v-if="seriesStore.observations.length" :observations="seriesStore.observations"/><p v-else class="empty">新序列暂无数据。请逐日录入至少 42 天观测后运行预测。</p><form v-if="canEdit" class="inline-form" @submit.prevent="add"><label>补录日期<input v-model="point.day" type="date" required/></label><label>需求量<input v-model.number="point.value" type="number" min="0" step=".01" required/></label><button :disabled="busy">录入观测</button><small>重复日期会被拒绝，现有记录不会覆盖。</small></form></template>
